/// What became of a push. sent: the platform accepted it. no_token: the phone has notifications off. not_allowed: the target is not a phone on the sender's account. throttled: over a limit, dropped. expired: its expiresAt had passed. not_set_up: this server cannot reach the phone's platform. failed: the platform refused it or could not be reached.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum PushResult {
    #[serde(rename = "sent")]
    Sent,
    #[serde(rename = "no_token")]
    NoToken,
    #[serde(rename = "not_allowed")]
    NotAllowed,
    #[serde(rename = "throttled")]
    Throttled,
    #[serde(rename = "expired")]
    Expired,
    #[serde(rename = "not_set_up")]
    NotSetUp,
    #[serde(rename = "failed")]
    Failed,
    /// A value added after this build, which it cannot act on.
    #[serde(other)]
    Unknown,
}

/// Where the phone wants its notifications delivered. The signature is the phone's device key's Ed25519 signature over the UTF-8 text `sikemux-push|<nonce>|<key>|<sha256 of the token, lowercase hex>`, so no other sign-in on the account can redirect the phone's notifications.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "platform")]
pub enum PushTokenRegistration {
    #[serde(rename = "apns")]
    Apns(ApnsTokenRegistration),
    #[serde(rename = "fcm")]
    Fcm(FcmTokenRegistration),
    /// A message added after this build, which it cannot act on.
    #[serde(other)]
    Unknown,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PushTokenState {
    /// Whether the server has a token for this phone.
    pub enabled: bool,
    pub updated_at: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Relay {
    /// The relay's HTTPS address, such as https://relay.sikemux.com/.
    pub url: String,
    /// Where the relay runs, for logs and settings screens.
    pub region: String,
    /// The UDP port of the relay's QUIC address discovery, or null when it has none.
    pub quic_port: Option<i64>,
}

/// Why a device left its account: removed from another device or the web, signed out on the device itself, or the account was deleted.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum RevokeReason {
    #[serde(rename = "removed")]
    Removed,
    #[serde(rename = "signed_out")]
    SignedOut,
    #[serde(rename = "account_deleted")]
    AccountDeleted,
    /// A value added after this build, which it cannot act on.
    #[serde(other)]
    Unknown,
}

/// A link, text or prompt to stash. A file is sent as its bytes instead, with Content-Type, X-Stash-Name (URI-encoded), and optionally X-Stash-Note and X-Stash-Target (URI-encoded JSON of a StashTarget), or X-Stash-Prompt with a prompt's id to attach it to that prompt. A file signed with SikemuxHost or SikemuxDevice also sends X-Body-Sha256, the body's SHA-256 in lowercase hex, which the signature covers in place of hashing the body.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind")]
pub enum StashAdd {
    #[serde(rename = "link")]
    Link(StashAddLink),
    #[serde(rename = "text")]
    Text(StashAddText),
    #[serde(rename = "prompt")]
    Prompt(StashAddPrompt),
    /// A message added after this build, which it cannot act on.
    #[serde(other)]
    Unknown,
}

/// A link to stash.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StashAddLink {
    /// An http or https link.
    pub url: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<StashNote>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub target: Option<StashTarget>,
}

/// A composer's whole prompt to stash: its text, with its files uploaded after it.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StashAddPrompt {
    pub text: String,
    /// How many files will follow, each uploaded with X-Stash-Prompt set to the prompt's id. Until the last arrives the prompt is in no list and announced to no device; one left unfinished for a day is deleted.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub attachment_count: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<StashNote>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub target: Option<StashTarget>,
}

/// Text to stash.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StashAddText {
    pub text: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<StashNote>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub target: Option<StashTarget>,
}

/// Something the person shared into Sikemux, kept on their account until they use it.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StashItem {
    pub id: StashItemId,
    pub kind: StashKind,
    /// Only on links.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub url: Option<String>,
    /// Only on text and prompts.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub text: Option<String>,
    /// Only on prompts: the files attached to the prompt, oldest first. They are not listed on their own, get no events of their own, and are taken and deleted with their prompt.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub attachments: Option<Vec<StashItem>>,
    /// Only on text and prompts: the links written in its words, in the order they first appear, without repeats.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub links: Option<Vec<StashLink>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<StashNote>,
    /// The file's name. Only on items with a file.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
    /// The file's media type. Only on items with a file.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub mime: Option<String>,
    /// The file's size in bytes. Only on items with a file.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub size: Option<i64>,
    /// Only links get one, and only once the server has read the page; null until then, or when it could not. The links in a text's or prompt's words have theirs in links.
    pub preview: Option<StashPreview>,
    pub target: Option<StashTarget>,
    pub created_at: String,
    /// When the item was attached to a prompt or delivered to its target; null until then. Taken items are deleted 30 days later.
    pub taken_at: Option<String>,
    /// The device that stashed the item, or null when the web app did.
    pub from_device: Option<DeviceKey>,
}

/// A stash item's id: 16 random bytes the server picks, in unpadded base64url.
pub type StashItemId = String;

/// What was shared. A link, text or prompt arrives as JSON; an image, video or file as its bytes. A prompt is a composer's whole prompt: its text and the files attached to it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum StashKind {
    #[serde(rename = "link")]
    Link,
    #[serde(rename = "text")]
    Text,
    #[serde(rename = "image")]
    Image,
    #[serde(rename = "video")]
    Video,
    #[serde(rename = "file")]
    File,
    #[serde(rename = "prompt")]
    Prompt,
    /// A value added after this build, which it cannot act on.
    #[serde(other)]
    Unknown,
}

/// A link written in a text's or prompt's words, exactly as it is written there, with what its page says about itself.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StashLink {
    pub url: String,
    /// Null until the server has read the page, or when it could not.
    pub preview: Option<StashPreview>,
}

/// A page of the stash, newest first.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StashList {
    pub items: Vec<StashItem>,
    /// Send as cursor for the next page. Absent on the last page.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub cursor: Option<StashListCursor>,
    /// When the person last looked at the stash on any device; items created after it are new. Null until they first do.
    pub seen_at: Option<String>,
}

/// Where the next page of a list starts. Opaque to apps.
pub type StashListCursor = String;

/// What the person wrote beside the item when they shared it.
pub type StashNote = String;

/// What a link's page says about itself, read by the server from its meta tags after the link was stashed.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StashPreview {
    pub title: String,
    /// The site's name, or its host name when the page names none.
    pub site: String,
    pub description: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub image_url: Option<String>,
    /// The site's icon, as the page names it.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub icon_url: Option<String>,
}

/// When the person last looked at the stash. Setting it only ever moves it forward, and never past the server's clock.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StashSeen {
    pub at: String,
}

/// Which items a list holds: those not used yet, those used, or both.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum StashTaken {
    #[serde(rename = "false")]
    False,
    #[serde(rename = "true")]
    True,
    #[serde(rename = "all")]
    All,
    /// A value added after this build, which it cannot act on.
    #[serde(other)]
    Unknown,
}

/// Where the person sent the item from the share sheet: a chat on a host (chatId), or a new chat in a project on it (projectPath with newChat true). That host puts it in the chat's draft and marks it taken.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StashTarget {
    pub host_key: DeviceKey,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub chat_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub project_path: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub new_chat: Option<bool>,
}

/// A change to an item: a new note, or taken true once it is used. A taken item cannot be untaken.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StashUpdate {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<StashNote>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub taken: Option<bool>,
}

/// Reads `json` as the named type and writes it back, for the contract tests.
#[cfg(test)]
pub(crate) fn round_trip(name: &str, json: &str) -> Option<super::RoundTrip> {
    use super::through;
    Some(match name {
        "Account" => through::<Account>(json),
        "AccountDeletion" => through::<AccountDeletion>(json),
        "AccountDeletionRequest" => through::<AccountDeletionRequest>(json),
        "AccountDeletionStatus" => through::<AccountDeletionStatus>(json),
        "AccountEvent" => through::<AccountEvent>(json),
        "AccountEventType" => through::<AccountEventType>(json),
        "AccountProfile" => through::<AccountProfile>(json),
        "AccountStatus" => through::<AccountStatus>(json),
        "ApiError" => through::<ApiError>(json),
        "ApnsEnvironment" => through::<ApnsEnvironment>(json),
        "ApnsTokenRegistration" => through::<PushTokenRegistration>(json),
        "AppVersion" => through::<AppVersion>(json),
        "Challenge" => through::<Challenge>(json),
        "Channel" => through::<Channel>(json),
        "ChannelVersions" => through::<ChannelVersions>(json),
        "Device" => through::<Device>(json),
        "DeviceKey" => through::<DeviceKey>(json),
        "DeviceList" => through::<DeviceList>(json),
        "DeviceRegistration" => through::<DeviceRegistration>(json),
        "DeviceRename" => through::<DeviceRename>(json),
        "DeviceRole" => through::<DeviceRole>(json),
        "ErrorCode" => through::<ErrorCode>(json),
        "ErrorDetail" => through::<ErrorDetail>(json),
        "EventId" => through::<EventId>(json),
        "FcmTokenRegistration" => through::<PushTokenRegistration>(json),
        "Health" => through::<Health>(json),
        "HealthStatus" => through::<HealthStatus>(json),
        "JoinRequest" => through::<JoinRequest>(json),
        "JoinTicket" => through::<JoinTicket>(json),
        "LiveAck" => through::<LiveDeviceMessage>(json),
        "LiveApp" => through::<LiveApp>(json),
        "LiveAuth" => through::<LiveDeviceMessage>(json),
        "LiveBye" => through::<LiveServerMessage>(json),
        "LiveChallenge" => through::<LiveServerMessage>(json),
        "LiveCloseCode" => through::<LiveCloseCode>(json),
        "LiveDeviceMessage" => through::<LiveDeviceMessage>(json),
        "LiveEvents" => through::<LiveServerMessage>(json),
        "LiveHello" => through::<LiveDeviceMessage>(json),
        "LiveLeave" => through::<LiveDeviceMessage>(json),
        "LivePing" => through::<LiveServerMessage>(json),
        "LivePong" => through::<LiveDeviceMessage>(json),
        "LivePush" => through::<LiveDeviceMessage>(json),
        "LivePushed" => through::<LiveServerMessage>(json),
        "LiveReady" => through::<LiveServerMessage>(json),
        "LiveReset" => through::<LiveServerMessage>(json),
        "LiveRevoked" => through::<LiveServerMessage>(json),
        "LiveRole" => through::<LiveRole>(json),
        "LiveServerMessage" => through::<LiveServerMessage>(json),
        "MinimumVersions" => through::<MinimumVersions>(json),
        "Network" => through::<Network>(json),
        "Platform" => through::<Platform>(json),
        "PushApp" => through::<PushApp>(json),
        "PushKind" => through::<PushKind>(json),
        "PushPlatform" => through::<PushPlatform>(json),
        "PushRef" => through::<PushRef>(json),
        "PushResult" => through::<PushResult>(json),
        "PushTokenRegistration" => through::<PushTokenRegistration>(json),
        "PushTokenState" => through::<PushTokenState>(json),
        "Relay" => through::<Relay>(json),
        "RevokeReason" => through::<RevokeReason>(json),
        "StashAdd" => through::<StashAdd>(json),
        "StashAddLink" => through::<StashAdd>(json),
        "StashAddPrompt" => through::<StashAdd>(json),
        "StashAddText" => through::<StashAdd>(json),
        "StashItem" => through::<StashItem>(json),
        "StashItemId" => through::<StashItemId>(json),
        "StashKind" => through::<StashKind>(json),
        "StashLink" => through::<StashLink>(json),
        "StashList" => through::<StashList>(json),
        "StashListCursor" => through::<StashListCursor>(json),
        "StashNote" => through::<StashNote>(json),
        "StashPreview" => through::<StashPreview>(json),
        "StashSeen" => through::<StashSeen>(json),
        "StashTaken" => through::<StashTaken>(json),
        "StashTarget" => through::<StashTarget>(json),
        "StashUpdate" => through::<StashUpdate>(json),
        _ => return None,
    })
}
